    answer: 6,
    explanation: "電子メールアドレスは氏名の一部を含むなど特定の個人の識別につながり、分析の対象でもないので（一）項目削除を適用します。勤務先の業種は分析の対象で、金融業などの区分だけでは個人の特定につながりにくいため加工なしとします。体重は分析の対象なので削除できませんが、121.3 のような特に大きい値は個人の特定につながるため（三）トップコーディングでまとめ、小数点以下までの細かい値は（四）丸めによって元のデータと照合しにくくします。よって正解はキです。",
