    id: "p-r06-14", exam: "r06", no: 14, chapter: 10,
    scenario: `
<p>A 社は医療品の販売を行う従業員 100 名の企業である。営業部では，オンプレミスのデータベースに顧客情報を格納している。</p>
<p>営業部では，図 1 に示すバックアップポリシーを順守している。</p>
<table>
<tr><td>1．　データベースは毎週日曜日にフルバックアップを，それ以外の日は毎日の増分バックアップを毎日，別のテープメディアに取得する。<br>2．　バックアップは 1 週間分保存する。<br>3．　データベースの目標復旧時点（RPO）は 24 時間とする。<br>4．　バックアップからの目標復旧時間（RTO）は 6 時間とする。<br>5．　バックアップを保存しているテープメディア（以下，バックアップテープという）は鍵付きのキャビネットに保管する。<br>6．　バックアップはシステムを停止せずに取得する。</td></tr>
</table>
<p>図1　営業部におけるバックアップポリシー</p>
<p>先日，金曜日に営業部では，アプリケーションの不具合によってデータベースの内部構造の破損（以下，論理破損という）が生じたので，データベースを復旧する必要が生じた。しかし，火曜日のバックアップテープが物理的に破損していたので，データベースをバックアップポリシーどおりには復旧できなかった。</p>
<p>そのため，営業部の情報セキュリティリーダーである B 課長は，論理破損が起き，かつ，バックアップテープが物理的に破損していたとしてもデータベースを復旧できるようにする再発防止策を検討し，効果の高いものを選んだ。</p>`,
