<p>A 社は，飲食店へのコンサルティングを行う従業員 50 名の企業である。A 社の全ての PC では，マルウェア対策ソフト（以下，X ソフトという）が有効にされている。ある日，総務部の情報セキュリティリーダーである C 課長は，部下の D さんから，次の連絡を受けた。</p>
