    question: "リーダシップのスタイルは，その組織の状況に合わせる必要がある。組織の状況とリーダシップのスタイルの関係に次のことが想定できるとすると，スポーツチームの監督のリーダシップのスタイルのうち，図中の d と考えられるものはどれか。<br><br>〔組織の状況とリーダシップのスタイルの関係〕<br>組織は発足当時，構成員や仕組みの成熟度が低いので，リーダが仕事本位のリーダシップで引っ張っていく。成熟度が上がるにつれ，リーダと構成員の人間関係が培われ，仕事本位から人間関係本位のリーダシップに移行していく。更に成熟度が進むと，構成員は自主的に行動できるようになり，仕事本位，人間関係本位のリーダシップがいずれも弱まっていく。<br><br>図：横軸を仕事本位のリーダシップ（左が強い，右が弱い），縦軸を人間関係本位のリーダシップ（上が強い，下が弱い）とした平面上に山形の曲線があり，曲線上に左から順に点 a，b，c，d がある。各点の位置は次のとおりである。<table><tr><th>点</th><th>仕事本位のリーダシップ</th><th>人間関係本位のリーダシップ</th></tr><tr><td>a</td><td>強い</td><td>弱い</td></tr><tr><td>b</td><td>強い</td><td>強い</td></tr><tr><td>c</td><td>弱い</td><td>強い</td></tr><tr><td>d</td><td>弱い</td><td>弱い</td></tr></table>",
